public enum AtmState { Idle, CardInserted, PinValidated, OperationSelected, Processing, CardEjected }

public class AtmMachine
{
    public AtmState State { get; private set; } = AtmState.Idle;
    private string? _insertedCardNumber;
    private Account? _authenticatedAccount;

    public void InsertCard(string cardNumber)
    {
        if (State != AtmState.Idle) return;
        _insertedCardNumber = cardNumber;
        State = AtmState.CardInserted;
    }

    public bool EnterPin(string pin)
    {
        if (State != AtmState.CardInserted) return false;
        _authenticatedAccount = Bank.Authenticate(_insertedCardNumber, pin);
        if (_authenticatedAccount == null)
        {
            State = AtmState.Idle;
            return false;
        }
        State = AtmState.PinValidated;
        return true;
    }

    public decimal Withdraw(decimal amount)
    {
        if (State != AtmState.PinValidated) throw new InvalidOperationException();
        State = AtmState.Processing;
        var result = _authenticatedAccount.Withdraw(amount);
        State = AtmState.PinValidated;
        return result;
    }
}
